:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --card-back: #3b3b5c;
  --card-front: #4a4a6e;
  --accent: #f5c542;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --focus: #f5c542;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--surface);
  padding: 12px 16px;
  border-radius: var(--radius);
}

.moves {
  font-size: 1.125rem;
  font-weight: 600;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: #ffd966;
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  aspect-ratio: 1 / 1;
  perspective: 600px;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  border-radius: var(--radius);
}

.card:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.35s ease;
  transform-style: preserve-3d;
  border-radius: var(--radius);
}

.card.flipped .card-inner {
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  backface-visibility: hidden;
  font-size: 1.5rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.9);
}

.card-back {
  background: var(--card-back);
  border: 2px solid #55557a;
  font-size: 1.25rem;
  color: var(--text-muted);
}

.card-front {
  background: var(--card-front);
  transform: rotateY(180deg);
}

.card.matched .card-front {
  box-shadow: inset 0 0 0 3px var(--accent);
}

.card.matched {
  cursor: default;
}

.win-message {
  min-height: 1.5em;
  text-align: center;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--accent);
}

@media (max-width: 400px) {
  body {
    padding: 12px;
  }
  .board {
    gap: 8px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .status-bar {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('board');
  const moveCountEl = document.getElementById('moveCount');
  const winMessageEl = document.getElementById('winMessage');
  const newGameBtn = document.getElementById('newGameBtn');

  let deck = [];
  let flipped = [];
  let matchedCount = 0;
  let moves = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function buildDeck() {
    const cards = [];
    COLORS.forEach((color, index) => {
      cards.push({ id: index, color });
      cards.push({ id: index, color });
    });
    return shuffle(cards);
  }

  function createCard(cardData, index) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'card';
    button.dataset.id = cardData.id;
    button.dataset.index = index;
    button.setAttribute('role', 'gridcell');
    button.setAttribute('aria-label', 'Hidden card');
    button.setAttribute('aria-pressed', 'false');

    const inner = document.createElement('span');
    inner.className = 'card-inner';

    const back = document.createElement('span');
    back.className = 'card-face card-back';
    back.textContent = '?';
    back.setAttribute('aria-hidden', 'true');

    const front = document.createElement('span');
    front.className = 'card-face card-front';
    front.style.backgroundColor = cardData.color;
    front.setAttribute('aria-hidden', 'true');

    inner.appendChild(back);
    inner.appendChild(front);
    button.appendChild(inner);
    button.addEventListener('click', onCardClick);
    return button;
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((cardData, index) => {
      board.appendChild(createCard(cardData, index));
    });
  }

  function onCardClick(event) {
    const card = event.currentTarget;
    if (lock || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.setAttribute('aria-pressed', 'true');
    card.setAttribute('aria-label', 'Revealed card');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [a, b] = flipped;
    if (a.dataset.id === b.dataset.id) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.disabled = true;
      b.disabled = true;
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      flipped = [];
      matchedCount++;
      if (matchedCount === COLORS.length) {
        winMessageEl.textContent = `You won in ${moves} moves!`;
      }
    } else {
      lock = true;
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.setAttribute('aria-pressed', 'false');
        b.setAttribute('aria-pressed', 'false');
        a.setAttribute('aria-label', 'Hidden card');
        b.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lock = false;
      }, 800);
    }
  }

  function resetGame() {
    deck = buildDeck();
    flipped = [];
    matchedCount = 0;
    moves = 0;
    lock = false;
    moveCountEl.textContent = '0';
    winMessageEl.textContent = '';
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
